"""Native XYZ copy chain from resident motion to player and playback points.

This proves a coordinate representation, not attacked end, units, participation,
resident historical tick validity, or the timing of a displayed frame. The exact
frame/source matcher and the native pitch geometry guard remain separate gates.
"""
NATIVE_SPANS = (
    (0x47D2078,bytes.fromhex("")),
    (0x47D46C4,bytes.fromhex("")),
    (0x4ABD9DC,bytes.fromhex("ff0300f9ff0b00b9ff0b00f9ff630039c0020291a84a409101812e91a84a409102c13491e3030091e40314aa050080d22e5bf497680280b96916088b08050011680200b9e80340f9280900f9e80b40b9ea1340b9281900b9e82b4079083d480b087d015328a10039e82f4079083d480b087d015328a5003908f0a75228290429")),
    (0x4AB1F78,bytes.fromhex("2000c03d0004803d208440ad228c41ad020c02ad000401adc0035fd6")),
    (0x457B130,bytes.fromhex("a1000591e00308aae20309aafa0efc97")),
    # The per-entity frame updater between its entity lookup and the entity copy: it zeroes the
    # endpoint packet, calls the producer (0x4ABD940), writes a delta when the entity differs and
    # calls the entity copy (0x4AB1F78). Build 27.0.1 inlines the producer and the copy here, seven
    # times inside the frame constructor, so this span is where that build's copies are checked.
    (0x4AB4DF8,bytes.fromhex("f40301aaff1300b900e4002fe01300fdff2b00b9e02300fdff4b00b9ff1b00f9ff730079ff2b00f9ffb30079610040f9f60303aa682840b9e3430091f80300aaf50302aae00302aae20308aabf220094f70318aa08535039a8000037e1430091e00313aaa0f8ff97a0000037c08641a9e3430091e20314aa3a020094e1430091e00313aa3ff4ff97")),
)


def verify_native(read,base):
    for at,expected in NATIVE_SPANS:
        if read(base+at,len(expected))!=expected:
            raise ValueError('Native motion/player/playback XYZ copy chain changed')
    return {'native_motion_xyz_to_player_point_copy_verified':True,
        'native_motion_xyz_to_frame_endpoint_copy_verified':True,
        'same_native_xyz_representation':True,'physical_units':None,
        'positive_y_attacked_end_verified':False,'historical_pose_tick_attested':False,
        'active_participation_verified':False,
        'scope':'Source instruction compatibility only. Resident motion must agree with the exact '
            'frame endpoint before it is historical evidence; actual pitch geometry and attacked '
            'orientation need their own source proofs.'}
